@RestController
@RequestMapping("/employees")
class EmployeeController {

    @PostMapping
    ResponseEntity<EmployeeView> create(@Valid @RequestBody CreateEmployeeRequest request) {
        EmployeeView created = employeeService.create(request);
        return ResponseEntity.created(URI.create("/employees/" + created.id())).body(created);
    }

    @GetMapping("/{id}")
    EmployeeView get(@PathVariable long id) {
        return employeeService.getById(id);
    }
}

